def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release (everything after '-')
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease is not None:
            prerelease_identifiers = prerelease.split('.')

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_key(identifiers):
        # If no pre-release, it sorts after one with pre-release
        if not identifiers:
            return (1,)  # Higher tuple, sorts later

        # Convert identifiers to comparable form
        converted = []
        for ident in identifiers:
            if ident.isdigit():
                # All-digit sorts as (0, numeric_value)
                converted.append((0, int(ident)))
            else:
                # Non-digit sorts as (1, string_value)
                converted.append((1, ident))

        return (0, tuple(converted))  # Pre-release sorts before non-prerelease

    def sort_key(v):
        major, minor, patch, prerelease_identifiers = parse_version(v)
        return (major, minor, patch, prerelease_key(prerelease_identifiers))

    # Stable sort
    return sorted(versions, key=sort_key)

